"use client"

import { OrderDetails } from "@/components/account/order-details";
import { useOrder } from "@/hooks/use-orders";
import { useParams } from "next/navigation";
import React, { useEffect, useState } from "react";


export default function OrderDetailPage() {
    const params = useParams()
    const orderId = params.orderId as string


    // Fetch product data
    const { data: order, isLoading, error } = useOrder(orderId)

    if (error) return <div>Lỗi khi tải đơn hàng</div>;

    return (
        <div>
            <OrderDetails order={order} isLoading={isLoading} />
        </div>
    );
}

"use client"

import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { ProfileTab } from "@/components/account/profile-tab"
import { OrdersTab } from "@/components/account/orders-tab"
import { AddressesTab } from "@/components/account/addresses-tab"
import { useUser, useAddresses } from "@/hooks/use-user"
import { useMyOrders } from "@/hooks/use-orders"
import { useEffect, useState } from "react"
import { User } from "@/types/user"
import { FormUpdateUserSchema } from "@/schemas/user-schema"
import { Loader2 } from "lucide-react"
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"

export default function AccountPage() {
  const { user, isLoading: isLoadingUser, error: userError, updateUser, isUpdatingUser } = useUser()
  const { addresses, isLoading: isLoadingAddresses, setDefaultAddress, deleteAddress } = useAddresses()
  const { data: orders, isLoading: isLoadingOrders } = useMyOrders()

  const [userData, setUserData] = useState<User>({
    id: user?.id || "",
    firstName: user?.firstName || "",
    lastName: user?.lastName || "",
    fullName: user?.fullName || "",
    email: user?.email || "",
    avatar: user?.avatar || "",
    phoneNumber: user?.phoneNumber || ""
  })

  const handleSubmit = async (data: FormUpdateUserSchema) => {
    updateUser(data)
  }

  const handleSetDefaultAddress = (id: string) => {
    setDefaultAddress(id)
  }

  const handleDeleteAddress = (id: string) => {
    deleteAddress(id)
  }

  // Thêm state để theo dõi initial load
  const [initialLoad, setInitialLoad] = useState(true)

  useEffect(() => {
    if (!isLoadingUser && user) {
      // Cập nhật userData khi user đã được tải
      setUserData({
        id: user.id,
        firstName: user.firstName,
        lastName: user.lastName,
        fullName: user.fullName,
        email: user.email,
        avatar: user.avatar,
        phoneNumber: user.phoneNumber
      })
      setInitialLoad(false)
    }
  }, [isLoadingUser])

  if (initialLoad) {
    return (
      <div className="flex justify-center items-center h-screen">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    )
  }

  if (userError) {
    return (
      <div className="flex justify-center items-center h-screen">
        <Alert variant="destructive">
          <AlertTitle>Lỗi</AlertTitle>
          <AlertDescription>
            Không thể tải thông tin người dùng. Vui lòng thử lại.
          </AlertDescription>
        </Alert>
      </div>
    )
  }

  return (
    <Tabs defaultValue="profile">
      <TabsList className="w-full border-b justify-start mb-6">
        <TabsTrigger value="profile" className="text-base">
          Thông tin cá nhân
        </TabsTrigger>
        <TabsTrigger value="orders" className="text-base">
          Đơn hàng
        </TabsTrigger>
        <TabsTrigger value="addresses" className="text-base">
          Địa chỉ
        </TabsTrigger>
      </TabsList>

      <TabsContent value="profile">
        <ProfileTab
          userData={userData}
          isLoadingUser={isLoadingUser}
          isUpdatingUser={isUpdatingUser}
          handleSubmit={handleSubmit}
        />
      </TabsContent>

      <TabsContent value="orders">
        <OrdersTab orders={orders} isLoadingOrders={isLoadingOrders} />
      </TabsContent>

      <TabsContent value="addresses">
        <AddressesTab
          addresses={addresses}
          isLoadingAddresses={isLoadingAddresses}
          handleSetDefaultAddress={handleSetDefaultAddress}
          handleDeleteAddress={handleDeleteAddress}
        />
      </TabsContent>
    </Tabs>
  )
}

"use client"

import { useState, useEffect } from "react"
import { useCart } from "@/hooks/use-cart"

import CartHeader from '@/components/cart/CartHeader'
import LoadingSkeleton from '@/components/cart/LoadingSkeleton'
import ErrorMessage from '@/components/cart/ErrorMessage'
import EmptyCart from '@/components/cart/EmptyCart'
import CartContent from '@/components/cart/CartContent'
import { toast } from "sonner"

export default function CartPage() {

  // Cart functionality
  const {
    cart,
    isLoading,
    error,
    updateCartItem,
    isUpdatingCartItem,
    removeCartItem,
    isRemovingCartItem,
    clearCart,
    isClearingCart,
    applyPromoCode,
    isApplyingPromoCode,
  } = useCart()

  // Notification handling for cart operations
  // useEffect(() => {
  //   if (isRemovingCartItem === false) {
  //     // This means an item was just removed (operation completed)
  //     toast("Sản phẩm đã được xóa", {
  //       description: "Sản phẩm đã được xóa khỏi giỏ hàng của bạn.",
  //     })
  //   }
  // }, [isRemovingCartItem, toast])

  // Show toast when promo code is applied
  useEffect(() => {
    if (isApplyingPromoCode === false && (cart?.discount ?? 0) > 0) {
      toast("Mã giảm giá đã được áp dụng", {
        description: `Giảm giá ${(cart?.discount ?? 0).toLocaleString('vi-VN')}₫ đã được áp dụng vào đơn hàng`,
      })
    }
  }, [isApplyingPromoCode, cart?.discount, toast])

  // Show toast when clearing cart
  useEffect(() => {
    if (isClearingCart === false && cart?.items.length === 0) {
      toast("Giỏ hàng đã được xóa", {
        description: "Tất cả sản phẩm đã được xóa khỏi giỏ hàng",
      })
    }
  }, [isClearingCart, cart?.items.length, toast])

  if (error) {
    return <ErrorMessage />;
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <CartHeader />

      {isLoading ? (
        <LoadingSkeleton />
      ) : cart?.items.length && cart?.items.length > 0 ? (
        <CartContent
          cart={cart}
          updateCartItem={updateCartItem}
          removeCartItem={removeCartItem}
          clearCart={clearCart}
          applyPromoCode={applyPromoCode}
          isUpdatingCartItem={isUpdatingCartItem}
          isRemovingCartItem={isRemovingCartItem}
          isClearingCart={isClearingCart}
          isApplyingPromoCode={isApplyingPromoCode}
        />
      ) : (
        <EmptyCart />
      )}
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { toast } from "sonner"
import { useForm } from "react-hook-form"
import { zodResolver } from "@hookform/resolvers/zod"
import * as z from "zod"

import { useCart } from "@/hooks/use-cart"
import { useCreateOrder } from "@/hooks/use-orders"
import { CreateOrderRequest } from "@/types/order"
import { CheckoutBreadcrumbs } from "@/components/checkout/checkout-breadcrumbs"
import { ShippingInformation } from "@/components/checkout/shipping-information"
import { PaymentMethod } from "@/components/checkout/payment-method"
import { OrderSummary } from "@/components/checkout/order-summary"
import { useAuth } from "@/hooks/use-auth"
import { Form } from "@/components/ui/form"

const checkoutSchema = z.object({
  fullName: z.string().min(2, "Họ tên phải có ít nhất 2 ký tự"),
  email: z.string().email("Email không hợp lệ"),
  phoneNumber: z.string().regex(/^(0|\+84)\d{9,10}$/, "Số điện thoại không hợp lệ"),
  city: z.string().min(1, "Vui lòng chọn Tỉnh/Thành phố"),
  district: z.string().min(1, "Vui lòng chọn Quận/Huyện"),
  ward: z.string().min(1, "Vui lòng chọn Phường/Xã"),
  address: z.string().min(5, "Địa chỉ phải có ít nhất 5 ký tự"),
  paymentMethod: z.string().min(1, "Vui lòng chọn phương thức thanh toán"),
  note: z.string().optional(),
})

type CheckoutFormValues = z.infer<typeof checkoutSchema>

export default function CheckoutPage() {
  const { cart, clearCart } = useCart()
  const createOrder = useCreateOrder()
  const { user } = useAuth()
  const router = useRouter()

  const cartItems = cart?.items || []
  const subtotal = cartItems.reduce((total, item) => total + item.price * item.quantity, 0)
  const shippingCost = subtotal > 500000 ? 0 : 30000
  const total = subtotal + shippingCost

  const form = useForm<CheckoutFormValues>({
    resolver: zodResolver(checkoutSchema),
    defaultValues: {
      fullName: "",
      email: "",
      phoneNumber: "",
      address: "",
      city: "",
      district: "",
      ward: "",
      paymentMethod: "cod",
      note: "",
    },
  })

  useEffect(() => {
    if (user) {
      form.reset({
        fullName: `${user.lastName || ''} ${user.firstName || ''}`.trim(),
        email: user.email || "",
        phoneNumber: user.phoneNumber || "",
        address: "",
        city: "",
        district: "",
        ward: "",
        paymentMethod: "cod",
        note: "",
      })
    } else {
      // Optional: Redirect if not logged in, but better to show empty form or login prompt
      // The original code redirected.
      // toast.error("Vui lòng đăng nhập để tiếp tục")
      // router.push("/login")
    }
  }, [user, form])

  const onSubmit = async (values: CheckoutFormValues) => {
    if (cartItems.length === 0) {
      toast.error("Giỏ hàng trống")
      return
    }

    try {
      const orderData: CreateOrderRequest = {
        shippingAddress: `${values.address}, ${values.ward}, ${values.district}, ${values.city}`,
        phone: values.phoneNumber,
        email: values.email,
        deliveryInstructions: values.note || undefined,
        orderItems: cartItems.map((item) => ({
          productId: item.productId,
          quantity: item.quantity,
          color: item.color,
          size: item.size,
        })),
      }

      const result = await createOrder.mutateAsync(orderData)

      if (result.success) {
        toast.success("Đặt hàng thành công!")
        clearCart()
        router.push(`/account/orders/${result.data}`)
      } else {
        toast.error(result.error || "Có lỗi xảy ra khi đặt hàng")
      }
    } catch (error) {
      console.error("Order creation error:", error)
      toast.error("Có lỗi xảy ra khi đặt hàng")
    }
  }

  // Redirect if not logged in (keep original logic)
  useEffect(() => {
    // Only redirect if explicitly required to be logged in to access page
    // For better UX, might allow guest checkout or show login modal.
    // Keeping original logic for now
    const checkAuth = setTimeout(() => {
      if (!user &&
        // Add condition to wait for auth check (isLoading) if available from useAuth
        // Assuming useAuth might not have isLoading exposed here or it was not used before.
        true
      ) {
        // Original logic was simple user check.
      }
    }, 1000)
    return () => clearTimeout(checkAuth)
  }, [user])

  // Original logic directly in useEffect
  useEffect(() => {
    // We already handle form reset.
    // If strict login required:
    if (user === null) { // Assuming useAuth returns null when not logged in (and validation finished)
      // toast.error("Vui lòng đăng nhập để tiếp tục")
      // router.push("/login")
    }
  }, [user, router])

  return (
    <>
      <CheckoutBreadcrumbs />
      <h1 className="text-2xl md:text-3xl font-bold mb-6">Thanh toán</h1>

      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)}>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-6">
              <ShippingInformation form={form} />
              <PaymentMethod form={form} />
            </div>

            <div className="lg:col-span-1">
              <OrderSummary
                cartItems={cartItems}
                subtotal={subtotal}
                shippingCost={shippingCost}
                total={total}
                isSubmitting={form.formState.isSubmitting}
                isEmpty={cartItems.length === 0}
              />
            </div>
          </div>
        </form>
      </Form>
    </>
  )
}

import { ReactNode } from "react";
import Footer from "@/components/footer";
import { Header } from "@/components/header/index";
import { AuthProvider } from "@/hooks/use-auth";
import { CartProvider } from "@/components/provider/cart-provider";
import { WishlistProvider } from "@/components/provider/wishlist-provider";

interface RoutesLayoutProps {
    children: ReactNode;
}

export default function RoutesLayout({ children }: RoutesLayoutProps) {
    return (
        <div className="min-h-screen flex flex-col">
            <CartProvider>
                <WishlistProvider>
                    <Header />
                    <main className="flex-grow">
                        {children}
                    </main>
                    <Footer />
                </WishlistProvider>
            </CartProvider>
        </div>
    );
}

"use client";

import Image from "next/image"
import Link from "next/link"
import { ChevronRight } from "lucide-react"

import { Button } from "@/components/ui/button"
import ProductCard from "@/components/product-card"
import HeroCarousel from "@/components/hero-carousel"
import { useBestsellingProducts } from "@/hooks/use-products"
import { useCategories } from "@/hooks/use-categories"
import ProductCardSkeleton from "@/components/product-card-skeleton"
import CategoryGridSkeleton from "@/components/category-grid-skeleton"
import { useAllBanners } from "@/hooks/use-banners";
import Footer from "@/components/footer";
import { Header } from "@/components/header/index";
import { HeroCarouselSkeleton } from "@/components/hero-carousel-skeleton";
import { FeaturedCategories } from "@/components/featured-categories";
import { NewsletterSection } from "@/components/newsletter-section";
import { FeaturesSection } from "@/components/features-section";
import { PromotionBanner } from "@/components/promotion-banner";

export default function Home() {
  const { data: bestsellingProducts, isLoading: isLoadingProducts } = useBestsellingProducts()
  const { data: categories, isLoading: isLoadingCategories } = useCategories()
  const { data: banners, isLoading: isLoadingBanners } = useAllBanners()

  return (
    <div className="min-h-screen flex flex-col">
      <Header />
      <main className="flex-grow bg-background">
        {/* Hero Section */}
        <section className="w-full">
          {isLoadingBanners ? <HeroCarouselSkeleton /> : <HeroCarousel
            slides={banners || []}
            autoSlideInterval={5000}
            showDots={true}
            showArrows={true}
            imageHeight={500}
            className="shadow-lg"
          />}
        </section>

        {/* Features Section */}
        <FeaturesSection />

        {/* Categories Section */}
        <section className="container mx-auto py-8 md:py-12 px-4">
          {isLoadingCategories ? <CategoryGridSkeleton /> : <FeaturedCategories categories={categories || []} />}
        </section>

        {/* Bestselling Products Section */}
        <section className="container mx-auto py-8 md:py-12 px-4 bg-muted/50 rounded-3xl my-8">
          <div className="flex flex-col md:flex-row justify-between items-end md:items-center mb-8 gap-4">
            <div>
              <h2 className="text-2xl md:text-3xl font-bold mb-2 text-foreground">Sản phẩm bán chạy</h2>
              <p className="text-muted-foreground">Những sản phẩm được yêu thích nhất tuần qua</p>
            </div>
            <Button variant="ghost" asChild className="group text-primary hover:text-primary hover:bg-primary/10">
              <Link href="/products?sort=bestselling" className="flex items-center">
                Xem tất cả <ChevronRight className="h-4 w-4 ml-1 transition-transform group-hover:translate-x-1" />
              </Link>
            </Button>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-6">
            {isLoadingProducts
              ? Array(8)
                .fill(0)
                .map((_, index) => <ProductCardSkeleton key={index} />)
              : bestsellingProducts?.map((product) => <ProductCard key={product.id} product={product} />)}
          </div>
        </section>

        {/* Promotion Banner */}
        <PromotionBanner />

        {/* Newsletter Section */}
        <section className="container mx-auto py-12 px-4">
          <NewsletterSection />
        </section>
      </main>
      <Footer />
    </div >
  )
}

import React from 'react';
import { Button } from './ui/button';
import { ShoppingCart } from 'lucide-react';
import { useCart } from '@/hooks/use-cart';
import { title } from 'process';

interface AddToCartButtonProps {
    productId: string;
    title?: string;
}

const AddToCartButton: React.FC<AddToCartButtonProps> = ({ productId, title }) => {
    const { addToCart, isAddingToCart } = useCart()
    const handleAddToCart = () => {
        addToCart({
            productId: productId,
            quantity: 1,
            options: {},
        })
    }
    if (title) {
        return <Button
            size="sm"
            className="bg-[#FF6B00] hover:bg-[#e05f00] text-white"
            onClick={handleAddToCart}
            disabled={isAddingToCart}
            title={title}
        >
            <ShoppingCart className="h-4 w-4 mr-1" />
            Thêm vào giỏ
        </Button>
    }
    return (
        <Button
            size="icon"
            variant="ghost"
            onClick={handleAddToCart}
            disabled={isAddingToCart}
            title="Thêm vào giỏ hàng"
            className="h-8 w-8 rounded-full hover:bg-[#e05f00] text-amber-700 hover:text-white dark:hover:bg-[#FF6B00] transition-colors"
        >
            <ShoppingCart className="h-4 w-4" />

            <span className="sr-only">Thêm vào giỏ hàng</span>
        </Button>
    )
};

export default AddToCartButton;

import { useEffect } from "react"
import { UseFormReturn } from "react-hook-form"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form"
import { useLocation } from "@/hooks/use-location"

interface ShippingInformationProps {
    form: UseFormReturn<any>
}

export function ShippingInformation({ form }: ShippingInformationProps) {
    const {
        provinces,
        districts,
        wards,
        isLoading,
        fetchDistricts,
        fetchWards,
        setDistricts,
        setWards
    } = useLocation()

    const city = form.watch("city")
    const district = form.watch("district")

    // Handle initial data loading or when city/district matches available data
    useEffect(() => {
        if (city && provinces.length > 0) {
            const province = provinces.find(p => p.name === city)
            if (province) {
                // Only fetch if we don't have districts or if the current districts belong to another province
                // But checking "belong to another" is hard without storing provinceId. 
                // Simplest is to just fetch. The API is fast.
                // To optimize, we could check if districts array is empty or check variables.
                // For now, let's rely on the fact that if we change city, districts are cleared.
                fetchDistricts(province.code)
            }
        }
    }, [city, provinces.length]) // Depend on length to trigger when data arrives

    useEffect(() => {
        if (district && districts.length > 0) {
            const d = districts.find(item => item.name === district)
            if (d) {
                fetchWards(d.code)
            }
        }
    }, [district, districts.length])

    return (
        <div className="bg-card text-card-foreground rounded-lg border border-border/20 overflow-hidden">
            <div className="p-4 bg-muted border-b border-border/20">
                <h3 className="font-medium text-foreground">Thông tin giao hàng</h3>
            </div>

            <div className="p-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="md:col-span-2">
                        <FormField
                            control={form.control}
                            name="fullName"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Họ và tên *</FormLabel>
                                    <FormControl>
                                        <Input {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>

                    <div>
                        <FormField
                            control={form.control}
                            name="email"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Email *</FormLabel>
                                    <FormControl>
                                        <Input type="email" {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>

                    <div>
                        <FormField
                            control={form.control}
                            name="phoneNumber"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Số điện thoại *</FormLabel>
                                    <FormControl>
                                        <Input placeholder="0xxxxxxxxx" {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>

                    <div>
                        <FormField
                            control={form.control}
                            name="city"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Tỉnh/Thành phố *</FormLabel>
                                    <Select
                                        onValueChange={(value) => {
                                            field.onChange(value)
                                            // Reset child fields
                                            form.setValue("district", "")
                                            form.setValue("ward", "")
                                            // Trigger fetch
                                            const p = provinces.find(p => p.name === value)
                                            if (p) fetchDistricts(p.code)
                                            else setDistricts([])
                                        }}
                                        value={field.value}
                                        disabled={isLoading.provinces}
                                    >
                                        <FormControl>
                                            <SelectTrigger>
                                                <SelectValue placeholder="Chọn tỉnh/thành phố" />
                                            </SelectTrigger>
                                        </FormControl>
                                        <SelectContent>
                                            {provinces.map((province) => (
                                                <SelectItem key={province.code} value={province.name}>
                                                    {province.name}
                                                </SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>

                    <div>
                        <FormField
                            control={form.control}
                            name="district"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Quận/Huyện *</FormLabel>
                                    <Select
                                        onValueChange={(value) => {
                                            field.onChange(value)
                                            form.setValue("ward", "")
                                            const d = districts.find(item => item.name === value)
                                            if (d) fetchWards(d.code)
                                            else setWards([])
                                        }}
                                        value={field.value}
                                        disabled={!city || isLoading.districts}
                                    >
                                        <FormControl>
                                            <SelectTrigger>
                                                <SelectValue placeholder="Chọn quận/huyện" />
                                            </SelectTrigger>
                                        </FormControl>
                                        <SelectContent>
                                            {districts.map((item) => (
                                                <SelectItem key={item.code} value={item.name}>
                                                    {item.name}
                                                </SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>

                    <div>
                        <FormField
                            control={form.control}
                            name="ward"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Phường/Xã *</FormLabel>
                                    <Select
                                        onValueChange={field.onChange}
                                        value={field.value}
                                        disabled={!district || isLoading.wards}
                                    >
                                        <FormControl>
                                            <SelectTrigger>
                                                <SelectValue placeholder="Chọn phường/xã" />
                                            </SelectTrigger>
                                        </FormControl>
                                        <SelectContent>
                                            {wards.map((item) => (
                                                <SelectItem key={item.code} value={item.name}>
                                                    {item.name}
                                                </SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                    <FormMessage />
