import { MobileMenu } from "./mobile-menu"
import { DesktopNav } from "./desktop-nav"
import { useCart } from "@/hooks/use-cart"
import { useWishlist } from "@/hooks/use-wishlist"

export function Header() {
    const [isScrolled, setIsScrolled] = useState(false)
    const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)
    const [showSuggestions, setShowSuggestions] = useState(false)
    const { cart } = useCart()
    const { wishlist } = useWishlist()
    const [cartItemCount, setCartItemCount] = useState(3) // Mock cart count
    const [wishlistItemCount, setWishlistItemCount] = useState(3) // Mock wishlist count

    const { user, isAuthenticated, logout } = useAuth()

    // Handle scroll effect
    useEffect(() => {
        const handleScroll = () => {
            setIsScrolled(window.scrollY > 10)
        }

        window.addEventListener("scroll", handleScroll)
        return () => window.removeEventListener("scroll", handleScroll)
    }, [])


    useEffect(() => {
        if (cart) {
            // Calculate total number of items in cart
            const itemCount = cart.items?.length || 0
            setCartItemCount(itemCount)
        }
    }, [cart])

    useEffect(() => {
        if (wishlist) {
            // Calculate total number of items in wishlist
            const itemCount = wishlist.items?.length || 0
            setWishlistItemCount(itemCount)
        }
    }, [wishlist])



    const getUserInitials = () => {
        if (!user?.email) return "U"
        return user.email
            .split(" ")
            .map((part) => part[0])
            .join("")
            .toUpperCase()
            .substring(0, 2)
    }

    return (
        <header
            className={`sticky top-0 z-50 w-full bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60 border-b border-border/20 transition-all duration-200 ${isScrolled ? "shadow-sm" : ""
                }`}
        >
            <div className="container mx-auto px-4">
                <div className="flex items-center justify-between h-16 md:h-20">
                    {/* Logo */}
                    <Link href="/" className="flex items-center">
                        <Image
                            src="/logo.png?height=40&width=120"
                            alt="ShopViet Logo"
                            width={120}
                            height={40}
                            className="h-8 md:h-10 w-auto dark:invert transition-transform duration-300 hover:scale-130"
                        />
                    </Link>


                    {/* Desktop Navigation */}
                    <DesktopNav />

                    {/* Search Bar */}
                    <div className="hidden md:flex relative flex-1 max-w-md mx-4">
                        <SearchInput />
                    </div>

                    {/* User Actions */}
                    <div className="flex items-center space-x-2 md:space-x-4">
                        <ThemeToggle />

                        {/* Mobile Search Toggle */}
                        <Button
                            variant="ghost"
                            size="icon"
                            className="md:hidden"
                            onClick={() => setShowSuggestions(!showSuggestions)}
                        >
                            <Search className="h-5 w-5" />
                        </Button>

                        {/* Wishlist */}
                        <Link href="/wishlist" className="relative hidden md:block">
                            <Button variant="ghost" size="icon">
                                <Heart className="h-5 w-5" />
                            </Button>
                            {wishlistItemCount > 0 && (
                                <Badge className="absolute -top-1 -right-1 bg-primary text-primary-foreground h-5 w-5 flex items-center justify-center p-0 text-xs rounded-full">
                                    {wishlistItemCount}
                                </Badge>
                            )}
                        </Link>

                        {/* Cart */}
                        <Link href="/cart" className="relative">
                            <Button variant="ghost" size="icon">
                                <ShoppingCart className="h-5 w-5" />
                                {cartItemCount > 0 && (
                                    <Badge className="absolute -top-1 -right-1 bg-primary text-primary-foreground h-5 w-5 flex items-center justify-center p-0 text-xs rounded-full">
                                        {cartItemCount}
                                    </Badge>
                                )}
                            </Button>
                        </Link>

                        {/* User Menu */}
                        <UserMenu
                            user={user}
                            isAuthenticated={isAuthenticated}
                            logout={logout}
                            getUserInitials={getUserInitials}
                        />

                        {/* Mobile Menu Toggle */}
                        <Button
                            variant="ghost"
                            size="icon"
                            className="md:hidden"
                            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                        >
                            {isMobileMenuOpen ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
                        </Button>
                    </div>
                </div>

                {/* Mobile Search Bar */}
                <div className={`md:hidden pb-3 ${showSuggestions ? 'block' : 'hidden'}`}>
                    <SearchInput />
                </div>
            </div>

            {/* Mobile Menu */}
            <MobileMenu
                isMobileMenuOpen={isMobileMenuOpen}
                setIsMobileMenuOpen={setIsMobileMenuOpen}
                isAuthenticated={isAuthenticated}
                logout={logout}
            />
        </header>
    )
}

