                        <Link href={backLink.href} className="text-sm text-blue-600 hover:underline">
                            ← {backLink.label}
                        </Link>
                    )}
                </div>

                <div className="flex items-center space-x-2">
                    <Button
                        variant={viewMode === "grid" ? "default" : "outline"}
