                    >
                        <Grid3X3 className="h-4 w-4" />
                        <span className="sr-only">Chế độ xem lưới</span>
                    </Button>
                    <Button
                        variant={viewMode === "list" ? "default" : "outline"}
                        size="icon"
                        className="hidden md:flex"
                        onClick={() => toggleViewMode("list")}
                        aria-label="List view"
                    >
                        <List className="h-4 w-4" />
                        <span className="sr-only">Chế độ xem danh sách</span>
                    </Button>

                    <Button
                        variant="outline"
                        size="sm"
                        className="md:hidden"
                        onClick={toggleMobileFilters}
                    >
                        {showMobileFilters ? (
                            <>
                                <X className="h-4 w-4 mr-2" />
                                Đóng
                            </>
                        ) : (
                            <>
                                <Filter className="h-4 w-4 mr-2" />
                                Lọc
                            </>
                        )}
                    </Button>

                    <Select value={sortBy} onValueChange={handleSortChange}>
                        <SelectTrigger className="w-[180px]">
                            <SelectValue placeholder="Sắp xếp theo" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="name">Tên</SelectItem>
                            <SelectItem value="featured">Nổi bật</SelectItem>
                            <SelectItem value="price-asc">Giá: Thấp đến cao</SelectItem>
                            <SelectItem value="price-desc">Giá: Cao đến thấp</SelectItem>
                            <SelectItem value="newest">Mới nhất</SelectItem>
                            <SelectItem value="rating">Đánh giá cao nhất</SelectItem>
                        </SelectContent>
                    </Select>
                </div>
            </div>

            <div className="flex flex-col md:flex-row gap-6">
                {/* Filters - Desktop */}
                <div className="hidden md:block w-64 flex-shrink-0">
                    <div className="sticky top-20">
                        <ProductFilters
                            categorySlug={categorySlug}
                            brandSlug={brandSlug}
                            onFiltersChange={handleFiltersChange}
                            initialFilters={{
                                ...(categorySlug ? { categoryIds: category?.id } : {}),
                                ...(brandSlug ? { brandIds: brand?.id } : {}),
                            }}
                        />
                    </div>
                </div>

                {/* Mobile Filters */}
                {showMobileFilters && (
                    <div className="md:hidden mb-6">
                        <ProductFilters
                            categorySlug={categorySlug}
                            brandSlug={brandSlug}
                            onFiltersChange={handleFiltersChange}
                            initialFilters={{
                                ...(categorySlug ? { categoryIds: category?.id } : {}),
                                ...(brandSlug ? { brandIds: brand?.id } : {}),
                            }}
                        />
                    </div>
                )}

                {/* Product Grid/List */}
                <div className="flex-1">
                    {isLoading ? (
                        viewMode === "grid" ? (
                            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-6">
                                {Array(12)
                                    .fill(0)
                                    .map((_, index) => (
                                        <ProductCardSkeleton key={index} />
                                    ))}
                            </div>
                        ) : (
                            <div className="space-y-4">
                                {Array(8)
                                    .fill(0)
                                    .map((_, index) => (
                                        <ProductListItemSkeleton key={index} />
                                    ))}
                            </div>
                        )
                    ) : products.length === 0 ? (
                        <div className="text-center py-16 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-dashed border-gray-200 dark:border-gray-800">
                            <div className="flex justify-center mb-4">
                                <div className="p-4 bg-white dark:bg-gray-800 rounded-full shadow-sm">
                                    <PackageOpen className="h-8 w-8 text-gray-400" />
                                </div>
                            </div>
                            <h3 className="text-lg font-medium text-gray-900 dark:text-gray-100 mb-2">
                                Không tìm thấy sản phẩm
                            </h3>
                            <p className="text-gray-500 dark:text-gray-400 mb-6 max-w-sm mx-auto">
                                Rất tiếc, chúng tôi không tìm thấy sản phẩm nào phù hợp với bộ lọc hiện tại của bạn.
                            </p>
                            <Button variant="outline" onClick={handleResetFilters}>
                                Xóa bộ lọc & Thử lại
                            </Button>
                        </div>
                    ) : viewMode === "grid" ? (
                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-6">
                            {products.map((product) => (
                                <ProductCard key={product.id} product={product} />
                            ))}
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {products.map((product) => (
                                <ProductListItem key={product.id} product={product} />
                            ))}
                        </div>
                    )}

                    {products.length > 0 && (
                        <div className="mt-8">
                            <Pagination
                                totalPages={totalPages}
                                currentPage={currentPage}
                                onPageChange={handlePageChange}
                            />
                        </div>
                    )}
                </div>
            </div>
        </div>
    )
}

"use client"

import { useCallback, useEffect, useState } from "react"
import { useProductReviews } from "@/hooks/use-products"
import { useAuth } from "@/hooks/use-auth"
import { useSignalR } from "@/hubs/signalr-context"
import { useMutation, useQueryClient } from "@tanstack/react-query"
import { toast } from "sonner"
import { RatingDistribution, Review } from "@/types/product"
import { RatingSummary } from "./reviews/rating-summary"
import { ReviewForm } from "./reviews/review-form"
import { ReviewItem } from "./reviews/review-item"
import { ReviewsFilter } from "./reviews/reviews-filter"
import { ReviewsLoadingSkeleton } from "./reviews/reviews-loading-skeleton"
import { ReviewsError } from "./reviews/reviews-error"
import { Button } from "@/components/ui/button"
import { useCreateReview, useCreateReviewReply } from "@/hooks/use-reviews"
import { CreateReviewRequest } from "@/services/review-service"

interface ProductReviewsProps {
  productId: string | undefined
}

interface TypingUser {
  userId: string
  userName: string
  isTyping: boolean
}

export default function ProductReviews({ productId }: ProductReviewsProps) {
  const { isAuthenticated, user } = useAuth()
  const {
    joinProductGroup,
    leaveProductGroup,
    sendTypingIndicator,
    onNewReview,
    onRatingUpdated,
    onReviewLikeUpdated,
    onUserTyping,
    isConnected
  } = useSignalR()

  const [typingUsers, setTypingUsers] = useState<TypingUser[]>([])
  const [isTyping, setIsTyping] = useState(false)
  const [typingTimeout, setTypingTimeout] = useState<NodeJS.Timeout | null>(null)

  const queryClient = useQueryClient()
  const { data, isLoading, error, refetch } = useProductReviews(productId || "")
  const [reviews, setReviews] = useState<Review[]>([])
  const [rating, setRating] = useState(0)
  const [reviewCount, setReviewCount] = useState(0)
  const [ratingDistribution, setRatingDistribution] = useState<RatingDistribution[]>([])

  useEffect(() => {
    if (data) {
      setReviews(data.reviews || [])
      setRating(data.rating || 0)
      setReviewCount(data.reviewCount || 0)
      setRatingDistribution(data.ratingDistribution || [])
    }
  }, [data])

  useEffect(() => {
    if (productId && isConnected) {
      joinProductGroup(productId)
      return () => {
        leaveProductGroup(productId)
      }
    }
  }, [productId, isConnected, joinProductGroup, leaveProductGroup])

  useEffect(() => {
    if (!isConnected) return

    const handleNewReview = (newReview: Review) => {
      setReviews(prev => [newReview, ...prev])
      // Chỉ thông báo nếu review không phải do chính người dùng hiện tại gửi
      if (newReview.applicationUserId !== user?.id) {
        toast.success('Có đánh giá mới!')
      }
    }

    const handleRatingUpdated = (data: { ProductId: string; NewRating: number; ReviewCount: number }) => {
      if (data.ProductId === productId) {
        setRating(data.NewRating)
        setReviewCount(data.ReviewCount)
        queryClient.invalidateQueries({ queryKey: ["product", productId, "reviews"] })
      }
    }

    const handleReviewLikeUpdated = (data: { ReviewId: string; LikeCount: number }) => {
      setReviews(prev =>
        prev.map(review =>
          review.id === data.ReviewId
            ? { ...review, likes: data.LikeCount }
            : review
        )
      )
    }

    const handleUserTyping = (data: { ProductId: string; UserId: string; UserName: string; IsTyping: boolean }) => {
      if (data.ProductId === productId) {
        setTypingUsers(prev => {
          const filtered = prev.filter(user => user.userId !== data.UserId)
          if (data.IsTyping) {
            return [...filtered, {
              userId: data.UserId,
              userName: data.UserName,
              isTyping: true
            }]
          }
          return filtered
        })

        setTimeout(() => {
          setTypingUsers(prev => prev.filter(user => user.userId !== data.UserId))
        }, 3000)
      }
    }

    onNewReview(handleNewReview)
    onRatingUpdated(handleRatingUpdated)
    onReviewLikeUpdated(handleReviewLikeUpdated)
    onUserTyping(handleUserTyping)

    return () => {
      // Clean up event listeners if needed
    }
  }, [isConnected, productId, onNewReview, onRatingUpdated, onReviewLikeUpdated, onUserTyping, queryClient])


  const likeReviewMutation = useMutation({
    mutationFn: async (reviewId: string) => {
      const response = await fetch(`/api/reviews/${reviewId}/like`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
          'Content-Type': 'application/json'
        }
      })

      if (!response.ok) {
        throw new Error('Failed to like review')
      }

      return response.json()
    }
  })

  const handleTyping = useCallback(() => {
    if (!isTyping && productId) {
      setIsTyping(true)
      sendTypingIndicator(productId, true)
    }

    if (typingTimeout) {
      clearTimeout(typingTimeout)
    }

    const timeout = setTimeout(() => {
      setIsTyping(false)
      if (productId) {
        sendTypingIndicator(productId, false)
      }
    }, 1000)

    setTypingTimeout(timeout)
  }, [isTyping, productId, sendTypingIndicator, typingTimeout])

  const createReviewMutation = useCreateReview();

  const handleSubmitReview = (rating: number, content: string) => {
    const reviewData: CreateReviewRequest = {
      productId: productId || "",
      rating,
      content,
      userId: user?.id || "",
    }
    createReviewMutation.mutate({
      ...reviewData,
      productId: productId || "",
    });
  }

  const handleLikeReview = (reviewId: string) => {
    likeReviewMutation.mutate(reviewId)
  }

  const handleSortChange = (value: string) => {
    // Implement sorting logic here
    console.log("Sort by:", value)
  }

  const handleLoginRequest = () => {
    // Implement login logic here
    console.log("Login requested")
  }

  if (isLoading) {
    return <ReviewsLoadingSkeleton />
  }

  if (error) {
    return <ReviewsError onRetry={() => refetch()} />
  }

  return (
    <div>
      <RatingSummary
        rating={rating}
        reviewCount={reviewCount}
        ratingDistribution={ratingDistribution}
      />

      <ReviewForm
        onSubmit={handleSubmitReview}
        isAuthenticated={isAuthenticated}
        onLoginRequest={handleLoginRequest}
      />

      <ReviewsFilter
        reviewCount={reviewCount}
        onSortChange={handleSortChange}
      />

      <div className="space-y-6">
        {reviews.length > 0 ? (
          reviews.map((review, index) => (
            <ReviewItem
              key={`${review.id}-${index}`}
              review={review}
              onLike={handleLikeReview}
            />
          ))
        ) : (
          <div className="text-center py-8">
            <p className="text-gray-500">Chưa có đánh giá nào cho sản phẩm này</p>
          </div>
        )}
      </div>

      {reviews.length > 0 && (
        <div className="mt-6 text-center">
          <Button variant="outline" className="border-[#2A5CAA] text-[#2A5CAA]">
            Xem thêm đánh giá
          </Button>
        </div>
      )}
    </div>
  )
}

