"use client"

import { toast } from "sonner"
import { cn } from "@/lib/utils"
import { CheckCircle, AlertCircle, AlertTriangle, Info, X } from "lucide-react"
import { Button } from "@/components/ui/button"
import { cva } from "class-variance-authority"

export type ToastType = "success" | "error" | "warning" | "info" | "default"

export interface AppToastProps {
    /**
     * The title of the toast
     */
    title?: string
    /**
     * The description of the toast
     */
    description?: string
    /**
     * The type of the toast
     * @default "default"
     */
    type?: ToastType
    /**
     * The duration of the toast in milliseconds
     * @default 4000
     */
    duration?: number
    /**
     * Whether to show a close button
     * @default false
     */
    showCloseButton?: boolean
    /**
     * Custom class name for the toast
     */
    className?: string
    /**
     * Action button configuration
     */
    action?: {
        label: string
        onClick: () => void
    }
    /**
     * ID for the toast (useful for dismissing specific toasts)
     */
    id?: string
}

const toastIconVariants = cva("h-5 w-5 flex-shrink-0", {
    variants: {
        type: {
            default: "text-foreground",
            success: "text-green-500",
            error: "text-red-500",
            warning: "text-amber-500",
            info: "text-blue-500",
        },
    },
    defaultVariants: {
        type: "default",
    },
})

const toastActionVariants = cva(
    "inline-flex items-center justify-center rounded-md text-sm font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 h-8 px-3 text-xs",
    {
        variants: {
            type: {
                default: "bg-primary text-primary-foreground hover:bg-primary/90",
                success: "bg-green-500 text-white hover:bg-green-600",
                error: "bg-red-500 text-white hover:bg-red-600",
                warning: "bg-amber-500 text-white hover:bg-amber-600",
                info: "bg-blue-500 text-white hover:bg-blue-600",
            },
        },
        defaultVariants: {
            type: "default",
        },
    },
)

export const AppToaster = {
    show: (props: AppToastProps) => {
        const { title, description, type = "default", duration, showCloseButton = false, className, action, id } = props


        return toast.custom(
            (data) => {
                // Safely access dismiss function from data
                const dismiss = typeof data === "object" && data && 'dismiss' in data ? (data as any).dismiss : undefined

                return (
                    <div className={cn("flex w-full flex-col gap-1.5", className)}>
                        <div className="flex items-start gap-3">
                            <div className="flex-shrink-0 mt-0.5">
                                {type === "success" && <CheckCircle className={toastIconVariants({ type })} />}
                                {type === "error" && <AlertCircle className={toastIconVariants({ type })} />}
                                {type === "warning" && <AlertTriangle className={toastIconVariants({ type })} />}
                                {type === "info" && <Info className={toastIconVariants({ type })} />}
                            </div>
                            <div className="flex-1 flex flex-col gap-1">
                                {title && <div className="font-medium leading-none tracking-tight">{title}</div>}
                                {description && <div className="text-sm text-muted-foreground">{description}</div>}
                                {action && (
                                    <div className="mt-2">
                                        <button
                                            className={toastActionVariants({ type })}
                                            onClick={() => {
                                                action.onClick()
                                                dismiss && dismiss()
                                            }}
                                        >
                                            {action.label}
                                        </button>
                                    </div>
                                )}
                            </div>
                            {showCloseButton && dismiss && (
                                <Button
                                    variant="ghost"
                                    size="icon"
                                    className="h-6 w-6 rounded-full opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                                    onClick={() => dismiss()}
                                >
                                    <X className="h-3.5 w-3.5" />
                                    <span className="sr-only">Close</span>
                                </Button>
                            )}
                        </div>
                    </div>
                )
            },
            {
                id,
                duration,
            },
        )
    },
    success: (props: Omit<AppToastProps, "type">) => AppToaster.show({ ...props, type: "success" }),
    error: (props: Omit<AppToastProps, "type">) => AppToaster.show({ ...props, type: "error" }),
    warning: (props: Omit<AppToastProps, "type">) => AppToaster.show({ ...props, type: "warning" }),
    info: (props: Omit<AppToastProps, "type">) => AppToaster.show({ ...props, type: "info" }),
    promise: <T,>(
        promise: Promise<T>,
        {
            loading,
            success,
            error,
        }: {
            loading: string | AppToastProps
            success: string | ((data: T) => AppToastProps)
            error: string | ((error: unknown) => AppToastProps)
        },
    ) => {
        return toast.promise(promise, {
            loading: typeof loading === "string" ? loading : (loading.title || "Loading..."),
            success: (data) => {
                const successProps = typeof success === "function" ? success(data) : success
                if (typeof successProps === "string") return successProps
                return successProps.description ? `${successProps.title || "Success"}: ${successProps.description}` : (successProps.title || "Success")
            },
            error: (err) => {
                const errorProps = typeof error === "function" ? error(err) : error
                if (typeof errorProps === "string") return errorProps
                return errorProps.description ? `${errorProps.title || "Error"}: ${errorProps.description}` : (errorProps.title || "Error")
            },
        })
    },
    dismiss: (toastId?: string) => {
        toast.dismiss(toastId)
    },
    dismissAll: () => {
        toast.dismiss()
    },
}

"use client"
import React, { createContext, useContext, useState, useEffect } from "react"
import authService, { User } from "@/services/auth-service"
import { useRouter } from "next/navigation"

interface AuthContextType {
    token: string | null
    user: User | null
    loading: boolean
    error: string | null
    isAuthenticated: boolean
    login: (email: string, password: string) => Promise<void>
    register: (registerData: { firstName: string; lastName: string; email: string; phoneNumber?: string, password: string, confirmPassword?: string }) => Promise<void>
    logout: () => Promise<void>
    clearError: () => void
}

const AuthContext = createContext<AuthContextType | undefined>(undefined)

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [user, setUser] = useState<User | null>(null)
    const [loading, setLoading] = useState<boolean>(true)
    const [error, setError] = useState<string | null>(null)
    const router = useRouter()

    // Check for existing authentication on mount
    useEffect(() => {
        const initAuth = async () => {
            setLoading(true)
            try {
                // Đảm bảo đồng bộ token giữa localStorage và cookie
                authService.syncAuthState()

                // Try to get stored user first
                const storedUser = authService.getStoredUser()

                if (storedUser && authService.isAuthenticated()) {
                    setUser(storedUser)

                    // Optionally verify with the server
                    try {
                        const currentUser = await authService.getCurrentUser()
                        if (currentUser.success && currentUser.data) {
                            setUser(currentUser.data)
                        }

                    } catch (err) {
                        // If verification fails, clear auth
                        await authService.logout()
                        setUser(null)
                    }
                }
            } catch (err) {
                console.error("Auth initialization error:", err)
                setUser(null)
            } finally {
                setLoading(false)
            }
        }

        initAuth()

        // Đồng bộ khi focus lại cửa sổ (chuyển tab, quay lại)
        window.addEventListener("focus", authService.syncAuthState)

        // Cleanup listener khi unmount
        return () => {
            window.removeEventListener("focus", authService.syncAuthState)
        }
    }, [])

    // Phần còn lại giữ nguyên
    const login = async (email: string, password: string) => {
        setLoading(true)
        setError(null)

        try {
            const data = await authService.login(email, password)
            const user: User = {
                id: data.data.userId,
                firstName: data.data.firstName,
                lastName: data.data.lastName,
                fullName: data.data.fullName,
                phoneNumber: data.data.phoneNumber,
                email: data.data.email,
                roles: data.data.roles,
                permissions: data.data.permissions,
                customerLevel: data.data.customerLevel
            }
            setUser(user)
            router.push("/dashboard")
        } catch (err: any) {
            const errorMessage = err.response?.data?.message || "Login failed. Please check your credentials."
            setError(errorMessage)
        } finally {
            setLoading(false)
        }
    }

    const register = async (registerData: {
        firstName: string
        lastName: string
        email: string
        phoneNumber?: string
        password: string,
        confirmPassword?: string,
    }) => {
        setLoading(true)
        setError(null)

        try {
            const data = await authService.register(registerData)

            const user: User = {
                id: data.data.userId,
                firstName: data.data.firstName,
                lastName: data.data.lastName,
                fullName: data.data.fullName,
                phoneNumber: data.data.phoneNumber,
                email: data.data.email,
                roles: data.data.roles,
                permissions: data.data.permissions,
                customerLevel: data.data.customerLevel
            }

            setUser(user)
            router.push("/dashboard")
        } catch (err: any) {
            const errorMessage = err.response?.data?.message || "Registration failed. Please try again."
            setError(errorMessage)
        } finally {
            setLoading(false)
        }
    }

    const logout = async () => {
        setLoading(true)

        try {
            await authService.logout()
            setUser(null)
            router.push("/login")
        } catch (err) {
            console.error("Logout error:", err)
        } finally {
            setLoading(false)
        }
    }

    const clearError = () => {
        setError(null)
    }

    const token = authService.getAuthToken()

    const value = {
        token,
        user,
        loading,
        error,
        isAuthenticated: !!user,
        login,
        register,
        logout,
        clearError
    }

    return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

// Custom hook to use auth context
export const useAuth = () => {
    const context = useContext(AuthContext)

    if (context === undefined) {
        throw new Error("useAuth must be used within an AuthProvider")
    }

    return context
}

