import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import cartService from "@/services/cart-service"
import { toast } from "sonner"

export function useCart() {
  const queryClient = useQueryClient()

  // Get cart
  const {
    data: cart,
    isLoading,
    error,
  } = useQuery({
    queryKey: ["cart"],
    queryFn: () => cartService.getCart(),
    staleTime: 1000 * 60 * 5, // 5 minutes
    select: (data) => {
      return data.data
    },
    throwOnError: true,
  })

  // Add to cart
  const addToCartMutation = useMutation({
    mutationFn: ({
      productId,
      quantity,
      options,
    }: {
      productId: string
      quantity: number
      options?: { color?: string; size?: string }
    }) => cartService.addToCart(productId, quantity, options),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["cart"] })
      toast.success("Thêm vào giỏ hàng thành công", {
        description: "Sản phẩm đã được thêm vào giỏ hàng của bạn.",
      })
    },
    onError: () => {
      toast.error("Thêm vào giỏ hàng thất bại", {
        description: "Có lỗi xảy ra khi thêm sản phẩm vào giỏ hàng.",
      })
    },
  })

  // Update cart item
  const updateCartItemMutation = useMutation({
    mutationFn: ({ itemId, quantity }: { itemId: string; quantity: number }) =>
      cartService.updateCartItem({ itemId, quantity }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["cart"] })
      toast.success("Cập nhật giỏ hàng thành công", {
        description: "Số lượng sản phẩm đã được cập nhật.",
      })
    },
    onError: () => {
      toast.error("Cập nhật giỏ hàng thất bại", {
        description: "Có lỗi xảy ra khi cập nhật giỏ hàng.",
      })
    },
  })

  // Remove cart item
  const removeCartItemMutation = useMutation({
    mutationFn: (itemId: string) => cartService.removeCartItem(itemId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["cart"] })
      toast.success("Xóa sản phẩm thành công", {
        description: "Sản phẩm đã được xóa khỏi giỏ hàng.",
      })
    },
    onError: () => {
      toast.error("Xóa sản phẩm thất bại", {
        description: "Có lỗi xảy ra khi xóa sản phẩm khỏi giỏ hàng.",
      })
    },
  })

  // Clear cart
  const clearCartMutation = useMutation({
    mutationFn: () => cartService.clearCart(),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["cart"] })
      toast.success("Xóa giỏ hàng thành công", {
        description: "Giỏ hàng của bạn đã được xóa.",
      })
    },
    onError: () => {
      toast.error("Xóa giỏ hàng thất bại", {
        description: "Có lỗi xảy ra khi xóa giỏ hàng.",
      })
    },
  })

  // Apply promo code
  const applyPromoCodeMutation = useMutation({
    mutationFn: (code: string) => cartService.applyPromoCode(code),
    onSuccess: (data: any) => {
      queryClient.invalidateQueries({ queryKey: ["cart"] })
      toast.success("Áp dụng mã giảm giá thành công", {
        description: data.data?.promoCode?.description || "Mã giảm giá đã được áp dụng.",
      })
    },
    onError: (error: any) => {
      toast.error("Áp dụng mã giảm giá thất bại", {
        description: error.response?.data?.error || "Mã giảm giá không hợp lệ.",
      })
    },
  })

  return {
    cart,
    isLoading,
    error,
    addToCart: addToCartMutation.mutate,
    isAddingToCart: addToCartMutation.isPending,
    updateCartItem: updateCartItemMutation.mutate,
    isUpdatingCartItem: updateCartItemMutation.isPending,
    removeCartItem: removeCartItemMutation.mutate,
    isRemovingCartItem: removeCartItemMutation.isPending,
    clearCart: clearCartMutation.mutate,
    isClearingCart: clearCartMutation.isPending,
    applyPromoCode: applyPromoCodeMutation.mutate,
    isApplyingPromoCode: applyPromoCodeMutation.isPending,
  }
}

"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import reviewService, { CreateReviewRequest } from "@/services/review-service";
import { toast } from "sonner"; // Assuming you're using sonner for notifications

export function useProductReviews(productId: string) {
    return useQuery({
        queryKey: ["reviews", productId],
        queryFn: () => reviewService.getProductReviews(productId),
        staleTime: 1000 * 60 * 5, // 5 minutes
        enabled: !!productId,
        select: (data) => {
            return data.data;
        },
        throwOnError: true,
    });
}

export function useCreateReview() {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: (data: CreateReviewRequest) => reviewService.createReview(data),
        onSuccess: (result, variables) => {
            // Invalidate and refetch product reviews
            queryClient.invalidateQueries({
                queryKey: ["reviews", variables.productId]
            });

            // Also invalidate product data to update review count/rating
            queryClient.invalidateQueries({
                queryKey: ["product", variables.productId]
            });

            if (result.success) {
                toast.success("Đánh giá được tạo thành công!");
            }
        },
        onError: (error: any) => {
            const errorMessage = error?.response?.data?.message || "Không tạo được đánh giá";
            toast.error(errorMessage);
        },
    });
}

export function useLikeReview() {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: (reviewId: string) => reviewService.likeReview(reviewId),
        onSuccess: (result, reviewId) => {
            // Invalidate all review queries to update like counts
            queryClient.invalidateQueries({
                queryKey: ["reviews"]
            });

            if (result.success) {
                toast.success("Đã thích!");
            }
        },
        onError: (error: any) => {
            const errorMessage = error?.response?.data?.message || "Lỗi khi thích đánh giá";
            toast.error(errorMessage);
        },
    });
}

export function useReviewReplies(reviewId: string) {
    return useQuery({
        queryKey: ["review-replies", reviewId],
        queryFn: () => reviewService.getReviewReplies(reviewId),
        staleTime: 1000 * 60 * 5, // 5 minutes
        enabled: !!reviewId,
        select: (data) => {
            return data.data;
        },
        throwOnError: true,
    });
}

export function useCreateReviewReply(productId: string | undefined, content: string) {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: ({ reviewId, content }: { reviewId: string; content: string }) =>
            reviewService.createReviewReply(reviewId, content),
        onSuccess: (result, variables) => {
            // Invalidate review replies
            queryClient.invalidateQueries({
                queryKey: ["review-replies", variables.reviewId]
            });

            // Also invalidate main reviews to update reply count
            queryClient.invalidateQueries({
                queryKey: ["reviews"]
            });

            if (result.success) {
                toast.success("Trả lời đánh giá thành công!");
