            // Update any cached query data that might contain this suggestion
            queryClient.invalidateQueries({
                queryKey: ["searchSuggestions"]
            });
        }
    });
}

export function useClearSearchHistory() {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: (userId: string) => searchSuggestionsService.clearSearchHistory(userId),
        onSuccess: () => {
            // Clear all search suggestions from cache
            queryClient.invalidateQueries({
                queryKey: ["searchSuggestions"]
            });
        }
    });
}

import axios from "axios"
import Cookies from "js-cookie" // Cần cài đặt: npm install js-cookie @types/js-cookie

// Create an axios instance with default config
const api = axios.create({
  baseURL: process.env.NEXT_PUBLIC_API_URL || "http://localhost:3000/api",
  headers: {
    "Content-Type": "application/json",
  },
  // withCredentials: true, // Enable sending cookies with requests
})

// Thêm hàm đồng bộ giữa localStorage và cookie
function syncTokens() {
  // Đồng bộ access token
  const localToken = localStorage.getItem("auth_token")
  const cookieToken = Cookies.get("auth_token")

  if (localToken && !cookieToken) {
    // Đồng bộ từ localStorage sang cookie
    Cookies.set("auth_token", localToken, {
      path: "/",
      expires: 1,  // 1 ngày
      sameSite: "strict"
    })
  } else if (!localToken && cookieToken) {
    // Đồng bộ từ cookie sang localStorage
    localStorage.setItem("auth_token", cookieToken)
  }

  // Đồng bộ refresh token
  const localRefreshToken = localStorage.getItem("refresh_token")
  const cookieRefreshToken = Cookies.get("refresh_token")

  if (localRefreshToken && !cookieRefreshToken) {
    Cookies.set("refresh_token", localRefreshToken, {
      path: "/",
      expires: 7,  // 7 ngày
      sameSite: "strict"
    })
  } else if (!localRefreshToken && cookieRefreshToken) {
    localStorage.setItem("refresh_token", cookieRefreshToken)
  }
}

// Đồng bộ token khi trang được tải
if (typeof window !== "undefined") {
  syncTokens()

  // Đồng bộ khi cửa sổ được tập trung lại (ví dụ: chuyển tab, quay lại)
  window.addEventListener("focus", syncTokens)
}

// Add a request interceptor for authentication
api.interceptors.request.use(
  (config) => {
    // Đồng bộ token trước khi thực hiện mỗi request
    if (typeof window !== "undefined") {
      syncTokens()
    }

    // Get token from localStorage
    const token = typeof window !== "undefined" ? localStorage.getItem("auth_token") : null

    if (token) {
      config.headers.Authorization = `Bearer ${token}`
    }

    return config
  },
  (error) => {
    return Promise.reject(error)
  }
)

// Add a response interceptor for error handling
api.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config

    // Handle expired token with refresh attempt
    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true

      try {
        // Attempt to refresh the token
        const { data } = await axios.post(
          `${process.env.NEXT_PUBLIC_API_URL || "http://localhost:3000/api"}/auth/refresh-token`,
          {
            accessToken: localStorage.getItem("auth_token"),
            refreshToken: localStorage.getItem("refresh_token"),
          },
          { withCredentials: true }
        )

        // If token refresh succeeds, update the token and retry
        if (data.data?.accessToken) {
          // Lưu vào cả localStorage và cookie
          localStorage.setItem("auth_token", data.data.accessToken)
          Cookies.set("auth_token", data.data.accessToken, {
            path: "/",
            expires: 1,
            sameSite: "strict"
          })

          if (data.data.refreshToken) {
            localStorage.setItem("refresh_token", data.data.refreshToken)
            Cookies.set("refresh_token", data.data.refreshToken, {
              path: "/",
              expires: 7,
              sameSite: "strict"
            })
          }

          api.defaults.headers.common["Authorization"] = `Bearer ${data.data.accessToken}`
          return api(originalRequest)
        }
      } catch (refreshError) {
        // If refresh fails, logout and redirect
        if (typeof window !== "undefined") {
          // Xóa token ở cả hai nơi
          localStorage.removeItem("auth_token")
          localStorage.removeItem("refresh_token")
          Cookies.remove("auth_token")
          Cookies.remove("refresh_token")
          // Use window.location instead of Router for redirection
          window.location.href = "/login"
        }
      }
    }

    // Handle other 401 errors (not token expiration)
    if (error.response?.status === 401 && originalRequest._retry) {
      if (typeof window !== "undefined") {
        localStorage.removeItem("auth_token")
        localStorage.removeItem("refresh_token")
        Cookies.remove("auth_token")
        Cookies.remove("refresh_token")
        // Use window.location instead of Router for redirection
        window.location.href = "/login"
      }
    }

    return Promise.reject(error)
  }
)

export default api

