            return response.data;
        } catch (error) {
            console.error(`Error posting data to ${urlEndpoint}:`, error);
            toast.error('Lỗi khi gửi dữ liệu', {
                description: `Không thể gửi dữ liệu đến ${urlEndpoint}. Vui lòng thử lại sau.`,
